fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    let rows = y.len();
    let cols = x.len();
    
    // Create first output matrix (X)
    let mut x_grid = Vec::with_capacity(rows);
    for _ in 0..rows {
        let row = x.clone();
        x_grid.push(row);
    }
    
    // Create second output matrix (Y)
    let mut y_grid = Vec::with_capacity(rows);
    for i in 0..rows {
        let mut row = Vec::with_capacity(cols);
        let y_val = y[i];
        for _ in 0..cols {
            row.push(y_val);
        }
        y_grid.push(row);
    }
    
    (x_grid, y_grid)
}